        m._r[2] = reg_t::bit_not(_r[2]);
        m._r[3] = reg_t::bit_not(_r[3]);
        m._r[4] = reg_t::bit_not(_r[4]);
        m._r[5] = reg_t::bit_not(_r[5]);
        m._r[6] = reg_t::bit_not(_r[6]);
        m._r[7] = reg_t::bit_not(_r[7]);
