        b |= bits_t(reg_t::bits(_r[3])) << (3 * reg_t::lanes);
        b |= bits_t(reg_t::bits(_r[4])) << (4 * reg_t::lanes);
        b |= bits_t(reg_t::bits(_r[5])) << (5 * reg_t::lanes);
        b |= bits_t(reg_t::bits(_r[6])) << (6 * reg_t::lanes);
