        auto x2 = _r[2];
        auto x3 = _r[3];
        auto x4 = _r[4];
        auto x5 = _r[5];
        auto x6 = _r[6];
        auto x7 = _r[7];
        x0 = reg_t::bit_or(x0, x4);
        x1 = reg_t::bit_or(x1, x5);
        x2 = reg_t::bit_or(x2, x6);
        x3 = reg_t::bit_or(x3, x7);
        x0 = reg_t::bit_or(x0, x2);
        x1 = reg_t::bit_or(x1, x3);
        x0 = reg_t::bit_or(x0, x1);
